<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #10131c;
      --panel: #1a2030;
      --bar: #4f8cff;
      --active: #ffb84d;
      --text: #edf2ff;
      --muted: #9ba8c7;
      --border: #2b3650;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at top, #202a40 0%, var(--bg) 55%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
    }

    .app {
      width: min(960px, calc(100vw - 32px));
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(26, 32, 48, 0.92);
      box-shadow: 0 18px 60px rgba(0, 0, 0, 0.35);
    }

    h1 {
      margin: 0 0 6px;
      font-size: clamp(1.35rem, 3vw, 2rem);
    }

    p {
      margin: 0 0 20px;
      color: var(--muted);
    }

    #bars {
      height: 340px;
      display: flex;
      align-items: end;
      gap: 5px;
      padding: 14px;
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: #0e121c;
    }

    .bar {
      flex: 1 1 0;
      min-width: 3px;
      position: relative;
      border-radius: 5px 5px 2px 2px;
      background: linear-gradient(to top, #376ed7, var(--bar));
      transition: height 100ms ease, background 100ms ease, transform 100ms ease;
    }

    .bar.active {
      background: linear-gradient(to top, #d58422, var(--active));
      transform: scaleX(1.04);
    }

    .bar::after {
      content: attr(data-value);
      position: absolute;
      left: 50%;
      bottom: calc(100% + 5px);
      transform: translateX(-50%);
      font-size: 11px;
      color: var(--muted);
      opacity: 0;
      pointer-events: none;
    }

    .bar:hover::after {
      opacity: 1;
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 18px;
    }

    button {
      border: 1px solid var(--border);
      border-radius: 9px;
      padding: 10px 16px;
      cursor: pointer;
      color: var(--text);
      background: #27334b;
      font: inherit;
      font-weight: 700;
      transition: background 150ms ease, transform 150ms ease;
    }

    button:hover {
      background: #344467;
      transform: translateY(-1px);
    }

    #sort {
      background: #2c66ca;
      border-color: #4782e8;
    }

    #sort:hover {
      background: #3976df;
    }

    #status {
      margin-left: auto;
      align-self: center;
      color: var(--muted);
      font-size: 0.92rem;
    }

    @media (max-width: 560px) {
      #bars {
        height: 260px;
        gap: 3px;
      }

      #status {
        width: 100%;
        margin-left: 0;
      }
    }
  </style>
</head>
<body>
  <main class="app">
    <h1>Sorting Visualizer</h1>
    <p>Bubble sort animation — orange bars are the current comparison.</p>

    <div id="bars" aria-label="Array bars"></div>

    <div class="controls">
      <button id="sort" type="button">Sort</button>
      <button id="shuffle" type="button">Shuffle</button>
      <button id="reset" type="button">Reset</button>
      <span id="status">Ready</span>
    </div>
  </main>

  <script>
    (() => {
      const barsElement = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");
      const statusElement = document.getElementById("status");

      const initialArray = [42, 15, 73, 28, 91, 8, 56, 34, 67, 19, 84, 49, 5, 62, 25, 77, 38, 96, 11, 53];
      let values = initialArray.slice();
      let outerIndex = 0;
      let innerIndex = 0;
      let finished = false;
      let activeIndices = [];
      let animationTimer = null;

      function resetSortState() {
        outerIndex = 0;
        innerIndex = 0;
        finished = values.length <= 1;
        activeIndices = [];
      }

      function isSorted() {
        for (let i = 1; i < values.length; i++) {
          if (values[i - 1] > values[i]) return false;
        }
        return true;
      }

      function render() {
        barsElement.innerHTML = "";

        const min = Math.min(...values, 0);
        const max = Math.max(...values, 1);
        const range = max - min || 1;

        values.forEach((value, index) => {
          const bar = document.createElement("div");
          bar.className = "bar";
          bar.dataset.value = value;
          bar.style.height = (8 + ((value - min) / range) * 88) + "%";

          if (activeIndices.includes(index)) {
            bar.classList.add("active");
          }

          barsElement.appendChild(bar);
        });

        statusElement.textContent = isSorted() ? "Sorted" : "Ready";
      }

      function stopAnimation() {
        if (animationTimer !== null) {
          clearInterval(animationTimer);
          animationTimer = null;
        }
      }

      /*
       * Performs exactly one Bubble Sort comparison each time it is called.
       * Returns true after the final required comparison has completed.
       */
      function sortStep() {
        if (finished || values.length <= 1) {
          finished = true;
          activeIndices = [];
          render();
          return true;
        }

        const left = innerIndex;
        const right = innerIndex + 1;
        activeIndices = [left, right];

        if (values[left] > values[right]) {
          const temporary = values[left];
          values[left] = values[right];
          values[right] = temporary;
        }

        innerIndex++;

        if (innerIndex >= values.length - outerIndex - 1) {
          outerIndex++;
          innerIndex = 0;
        }

        if (outerIndex >= values.length - 1) {
          finished = true;
        }

        render();
        return finished;
      }

      function setArray(array) {
        stopAnimation();
        values = Array.from(array, Number);
        resetSortState();
        render();
      }

      function shuffle() {
        stopAnimation();

        for (let i = values.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [values[i], values[j]] = [values[j], values[i]];
        }

        resetSortState();
        render();
      }

      function animateSort() {
        stopAnimation();

        if (isSorted()) {
          finished = true;
          render();
          return;
        }

        statusElement.textContent = "Sorting...";

        animationTimer = setInterval(() => {
          const done = sortStep();
          if (done) {
            stopAnimation();
            activeIndices = [];
            render();
          }
        }, 45);
      }

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", () => setArray(initialArray));

      window.viz = {
        array() {
          return values.slice();
        },
        setArray(array) {
          setArray(array);
        },
        sortStep() {
          return sortStep();
        },
        sorted() {
          return isSorted();
        }
      };

      render();
    })();
  </script>
</body>
</html>
